Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
using namespace std;

long long ones[20];

int count_ones(long long n, int i) {
    if (n == 0 || i == 0) return 0;
    long long current_block = ones[i];
    int max_full_blocks = n / current_block;
    int result = max_full_blocks * i;
    long long remainder = n % current_block;
    if (remainder == 0) return result;
    int option1 = i + count_ones(ones[i] - remainder, i - 1);
    int option2 = count_ones(remainder, i - 1);
    return result + min(option1, option2);
}

int main() {
    ones[0] = 0;
    for (int i = 1; i <= 16; ++i) {
        ones[i] = ones[i - 1] * 10 + 1;
    }
    long long n;
    cin >> n;
    cout << count_ones(n, 16) << endl;
    return 0;
}
